namespace ghidra.graph;




//TODO Do we need this class
public class GraphPathSet<V> {

	private Set<GraphPath<V>> paths = new();

	public bool containSomePathStartingWith(GraphPath<V> otherPath) {
		foreach (GraphPath<V> path in paths) {
			if (path.startsWith(otherPath)) {
				return true;
			}
		}
		return false;
	}

	public void add(GraphPath<V> path) {
		paths.add(path);
	}

	public Set<GraphPath<V>> getPathsContaining(V v) {
		Set<GraphPath<V>> set = new();
		foreach (GraphPath<V> path in paths) {
			if (path.contains(v)) {
				set.add(path);
			}
		}
		return set;
	}

	public int size() {
		return paths.size();
	}

	/* @Override */
	public string toString() {
		StringBuilder buf = new StringBuilder();
		foreach (GraphPath<V> path in paths) {
			buf.append(path.toString()).append('\n');
		}
		return buf.toString();
	}

}
